@CrossOrigin
@RestController
@RequestMapping("/ExposureQuery")
public class ExposureQueryRestController extends BaseSpringRestController {
	
	public ExposureQueryRestController( ExposureService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Exposure using a UUID
     * @param		UUID exposureId
     * @return		Exposure
     */    
    @GetMapping("/load")
    public Exposure load( @RequestParam(required=true) UUID exposureId ) {
    	Exposure entity = null;

    	try {  
    		entity = service.getExposure( new ExposureFetchOneSummary( exposureId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Exposure using Id " + exposureId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Exposure business objects
     * @return		Set<Exposure>
     */
    @GetMapping("/")
    public List<Exposure> loadAll() {                
    	List<Exposure> exposureList = null;
        
    	try {
            // load the Exposure
            exposureList = service.getAllExposure();
            
            if ( exposureList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Exposures" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Exposures ", exc );
        	return null;
        }

        return exposureList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Exposure exposure = null;
    protected ExposureService service = null;
    private static final Logger LOGGER = Logger.getLogger(ExposureQueryRestController.class.getName());
    
}
